import{bQ as t,aL as o,u as l,G as a}from"./chunks/framework.C1gZXFVa.js";const u=JSON.parse('{"title":"版本发布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/releases.md","filePath":"guide/releases.md"}'),d={name:"guide/releases.md"};function c(i,e,r,s,n,h){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="版本发布" tabindex="-1">版本发布 <a class="header-anchor" href="#版本发布" aria-label="Permalink to &quot;版本发布&quot;">​</a></h1><blockquote><p><strong>当前版本 2.0.0</strong>（2026-10-27）：针对当前系统的整体重构。本页是摘要，完整说明见主仓库 <a href="https://github.com/ghl1024/ansible-offline-install/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a> 与 <a href="https://github.com/ghl1024/ansible-offline-install/releases/tag/v2.0.0" target="_blank" rel="noreferrer">GitHub Release</a>。</p></blockquote><h2 id="_2-0-0-主要内容" tabindex="-1">2.0.0 主要内容 <a class="header-anchor" href="#_2-0-0-主要内容" aria-label="Permalink to &quot;2.0.0 主要内容&quot;">​</a></h2><ul><li>离线安装器 <code>install.sh</code>：基于本地 wheelhouse 与独立 Python venv，pip 全程 <code>--no-index</code>，安装时零网络。</li><li>打包脚本 <code>scripts/make-offline-bundle.sh</code>：产出带版本号的 <code>.tar.gz</code> 离线包与 SHA256 校验文件。</li><li>支持矩阵：EL 9 系列（Rocky / Alma / RHEL / CentOS Stream 9）、Ubuntu 24.04 / 22.04、Debian 12，x86_64 与 ARM64 共 8 个组合；CI 与 Release 流水线覆盖同样的 8 个组合，构建、安装测试、发布全自动。</li><li>Ansible 锁定 <code>ansible-core==2.18.19</code>，要求 Python &gt;= 3.11；两个脚本都会自动探测满足版本的解释器。</li><li>Galaxy collections 随包离线安装：默认附带 <code>ansible.posix</code> 与 <code>community.general</code>（含依赖）。</li><li>脚本默认中文界面，<code>--lang en</code> 或 <code>ANSIBLE_OFFLINE_LANG=en</code> 切英文；README 提供中英文双语版。</li><li>四个发布平台：GitHub 主仓库，Gitee / GitCode / CNB 国内镜像，Release 内容一致（见<a href="/guide/download">下载与校验</a>）。</li></ul><h2 id="资产构成" tabindex="-1">资产构成 <a class="header-anchor" href="#资产构成" aria-label="Permalink to &quot;资产构成&quot;">​</a></h2><blockquote><p>每个 Release 共 <strong>16 个资产</strong>：</p></blockquote><ul><li>8 个平台组合的离线包</li><li>8 个同名 <code>.sha256</code> 校验文件</li></ul><h2 id="路线图-已完成" tabindex="-1">路线图（已完成） <a class="header-anchor" href="#路线图-已完成" aria-label="Permalink to &quot;路线图（已完成）&quot;">​</a></h2><ul><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>Galaxy collections 随包离线安装</li><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>CI：脚本检查 + 8 种系统/架构组合的安装测试</li><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>Release 离线包覆盖 x86_64 与 ARM64，由 GitHub Actions 在原生 ARM64 机器上自动构建、实测并发布</li><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>本文档站上线（源码私有，构建产物发布到主仓库 GitHub Pages）</li></ul><h2 id="仓库结构" tabindex="-1">仓库结构 <a class="header-anchor" href="#仓库结构" aria-label="Permalink to &quot;仓库结构&quot;">​</a></h2><ul><li>主仓库的文件，按「你会用到的顺序」排列：</li></ul><table tabindex="0"><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><code>install.sh</code></td><td>离线机上运行的安装脚本，普通用户只需要这一个</td></tr><tr><td><code>scripts/make-offline-bundle.sh</code></td><td>联网机上打包的构建脚本</td></tr><tr><td><code>requirements.txt</code></td><td>ansible-core 版本锁定</td></tr><tr><td><code>collections-requirements.yml</code></td><td>随包附带的 collections 清单</td></tr><tr><td><code>.github/workflows/ci.yml</code></td><td>CI：脚本检查 + 8 种系统/架构组合的安装测试</td></tr><tr><td><code>.github/workflows/release.yml</code></td><td>发版：8 个目标的离线包自动构建、实测与发布</td></tr><tr><td><code>CHANGELOG.md</code></td><td>版本更新记录</td></tr><tr><td><code>LICENSE</code></td><td>MIT 许可证</td></tr></tbody></table>',12)])])}const k=t(d,[["render",c]]);export{u as __pageData,k as default};
